        let glsl_tes = "\nlayout(quads, point_mode) in;\nlayout(std430, binding = 2) buffer TESuint {\n  uint data[1];\n} g_uint_tes;\nlayout(std430, binding = 3) buffer TESint {\n  int data[1];\n} g_int_tes;\nuniform uint g_uint_value[8] = uint[8](3u, 1u, 2u, 0x1u, 0x3u, 0x1u, 0x2u, 0x7u);\nvoid main() {\n  gl_Position = gl_in[0].gl_Position;\n\nif (gl_TessCoord.x >= 0.5 || gl_TessCoord.y >= 0.5) return;\n  if (atomicExchange(g_uint_tes.data[gl_PrimitiveID], g_uint_value[1]) != 0u) return;\n  if (atomicAdd(g_uint_tes.data[gl_PrimitiveID], g_uint_value[2]) != 1u) return;\n  if (atomicMin(g_uint_tes.data[gl_PrimitiveID], g_uint_value[1]) != 3u) return;\n  if (atomicMax(g_uint_tes.data[gl_PrimitiveID], g_uint_value[2]) != 1u) return;\n  if (atomicAnd(g_uint_tes.data[gl_PrimitiveID], g_uint_value[3]) != 2u) return;\n  if (atomicOr(g_uint_tes.data[gl_PrimitiveID], g_uint_value[4]) != 0u) return;\n  if (g_uint_value[0] > 0u) {\n    if (atomicXor(g_uint_tes.data[gl_PrimitiveID], g_uint_value[5]) != 3u) return;\n  }\n  if (atomicCompSwap(g_uint_tes.data[gl_PrimitiveID], g_uint_value[6], g_uint_value[7]) != 2u) {\n    g_uint_tes.data[gl_PrimitiveID] = 1u;\n    return;\n  }\n\n  if (atomicExchange(g_int_tes.data[gl_PrimitiveID], 1) != 0) return;\n  if (atomicAdd(g_int_tes.data[gl_PrimitiveID], 2) != 1) return;\n  if (atomicMin(g_int_tes.data[gl_PrimitiveID], 1) != 3) return;\n  if (atomicMax(g_int_tes.data[gl_PrimitiveID], 2) != 1) return;\n  if (atomicAnd(g_int_tes.data[gl_PrimitiveID], 0x1) != 2) return;\n  if (atomicOr(g_int_tes.data[gl_PrimitiveID], 0x3) != 0) return;\n  if (atomicXor(g_int_tes.data[gl_PrimitiveID], 0x1) != 3) return;\n  if (atomicCompSwap(g_int_tes.data[gl_PrimitiveID], 0x2, 0x7) != 2) {\n    g_int_tes.data[gl_PrimitiveID] = 1;\n    return;\n  }\n}";
        let glsl_fs = "\nlayout(location = 0) out vec4 g_fs_out;\nvoid main() {\n  g_fs_out = vec4(0, 1, 0, 1);\n}";
